"""Additional scientific models for the next24 batch. All time/data claims are explicit."""
from html import escape
import json,math,textwrap

def e(x):return escape(str(x),quote=True)
def wrap_svg(text,x,y,width=190,size=23,linechars=18,bold=False):
 lines=[]
 for line in str(text).split('\n'):lines.extend(textwrap.wrap(line,width=linechars,break_long_words=False) or [''])
 return '<text x="'+str(x)+'" y="'+str(y)+'" text-anchor="middle" font-size="'+str(size)+'" font-weight="'+('700' if bold else '400')+'">'+''.join('<tspan x="'+str(x)+'" dy="'+('0' if i==0 else str(round(size*1.2)))+'">'+e(line)+'</tspan>' for i,line in enumerate(lines))+'</text>'
SVG_HEAD='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 500" font-family="Segoe UI, Arial, sans-serif" fill="#1f2937" role="img" '
COLORS=['#4E7A9B','#C9803B','#3F7D6E']

def model_html(spec,uid):
 mode=spec.get('mode')
 if mode=='growth':
  g=spec['growth'];assert len(g['dates'])==len(g['days'])>=3 and 1<=len(g['series'])<=3
  assert all(len(s['values'])==len(g['dates']) for s in g['series']);assert g['days']==sorted(g['days']) and len(set(g['days']))==len(g['days'])
  maximum=max(float(v) for s in g['series'] for v in s['values']);top=math.ceil(maximum/2)*2 or 2;span=g['days'][-1]-g['days'][0]
  svg=SVG_HEAD+'aria-label="Dated constructed growth record. Step through the supplied dates; future points are hidden until selected.">'
  svg+='<text x="95" y="35" font-size="25">Height / '+e(g.get('unit','cm'))+'</text><line x1="100" y1="80" x2="100" y2="375" stroke="#1f2937" stroke-width="3"/><line x1="100" y1="375" x2="940" y2="375" stroke="#1f2937" stroke-width="3"/>'
  for val in [0,top/2,top]:
   y=375-val/top*290;svg+=f'<line x1="100" y1="{y}" x2="940" y2="{y}" stroke="#e2e8f0"/><text x="80" y="{y+8}" text-anchor="end" font-size="23">{val:g}</text>'
  for i,day in enumerate(g['days']):
   x=120+(day-g['days'][0])/span*800;svg+=f'<text x="{x}" y="412" text-anchor="middle" font-size="22">Day {day}</text>'
  for j,s in enumerate(g['series']):
   color=COLORS[j];last=None
   for i,v in enumerate(s['values']):
    x=120+(g['days'][i]-g['days'][0])/span*800;y=375-v/top*290
    if last:svg+=f'<line data-growth-day="{i}" x1="{last[0]}" y1="{last[1]}" x2="{x}" y2="{y}" stroke="{color}" stroke-width="4" hidden=""/>'
    svg+=f'<circle data-growth-day="{i}" cx="{x}" cy="{y}" r="7" fill="{color}"'+(' hidden=""' if i else '')+'/>';last=(x,y)
   x=95+j*300;svg+=f'<line x1="{x}" y1="455" x2="{x+25}" y2="455" stroke="{color}" stroke-width="5"/><text x="{x+36}" y="463" font-size="22">{e(s["name"])}</text>'
  svg+='</svg>'
  return '<div class="lab-model" data-model="growth" data-growth="'+e(json.dumps(g))+'"><h4>Dated growth-record player</h4><p>'+e(g['note'])+'</p>'+svg+'<div class="lab-model-controls"><button type="button" data-growth-previous>Previous date</button><button type="button" data-growth-next>Next date</button><button type="button" data-growth-play>Play records</button><button type="button" data-growth-reset>First date</button></div><p data-growth-output class="lab-model-output" role="status" aria-live="polite"></p><input type="hidden" data-note data-model-record aria-label="Growth model selected record"><p class="lab-animation-note">Each point is a supplied dated record. Connecting lines help compare the pattern; they are not extra observations. Playback timing is arbitrary. Today’s real plants cannot complete days of growth during this lesson.</p></div>'
 if mode=='friction':
  f=spec['friction'];assert 2<=len(f['surfaces'])<=4 and all(s['distanceCm']>0 for s in f['surfaces'])
  svg=SVG_HEAD+'aria-label="Sliding-object distance replay. Same release setup; the endpoint uses the supplied stopping-distance data."><defs><marker id="'+uid+'-friction-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7 Z" fill="#b45309"/></marker></defs><text x="70" y="42" font-size="25">Compare the same object and release setup</text><rect x="65" y="285" width="870" height="22" fill="#cbd5e1"/><line x1="130" y1="170" x2="130" y2="310" stroke="#64748b" stroke-width="3" stroke-dasharray="8 7"/><text x="90" y="350" font-size="23">Start</text><g data-friction-runner class="friction-runner"><rect x="130" y="220" width="80" height="65" fill="#4E7A9B" stroke="#1f2937" stroke-width="3"/><text x="170" y="210" font-size="23" text-anchor="middle">Object</text><line data-friction-force x1="175" y1="265" x2="90" y2="265" stroke="#b45309" stroke-width="4" marker-end="url(#'+uid+'-friction-arrow)"/></g><line data-friction-end x1="750" y1="170" x2="750" y2="310" stroke="#3f7d6e" stroke-width="3" stroke-dasharray="5 6"/><text data-friction-end-label x="730" y="350" font-size="23">Endpoint</text><text x="190" y="400" font-size="23">During sliding, friction opposes that motion.</text><text x="190" y="439" font-size="22">Distance is scaled. Replay duration is not a measurement.</text></svg>'
  return '<div class="lab-model" data-model="friction" data-friction="'+e(json.dumps(f))+'"><h4>Compare stopping-distance records</h4><p>'+e(f['note'])+'</p><div class="lab-model-controls">'+''.join('<button type="button" data-friction-surface="'+str(i)+'" aria-pressed="'+str(i==0).lower()+'">'+e(s['name'])+'</button>' for i,s in enumerate(f['surfaces']))+'</div>'+svg+'<div class="lab-model-controls"><button type="button" data-friction-play>Replay this record</button><button type="button" data-friction-endpoint>Show endpoint</button><button type="button" data-friction-reset>Return to start</button></div><p data-friction-output class="lab-model-output" role="status" aria-live="polite"></p><input type="hidden" data-note data-model-record aria-label="Friction selected record"><p class="lab-animation-note">This is an illustration of the supplied endpoint, not a force or speed simulation. It cannot predict a new surface. With reduced motion, use Show endpoint.</p></div>'
 if mode=='separation':
  sep=spec['separation'];assert 3<=len(sep['cases'])<=5
  panels=[]
  for i,c in enumerate(sep['cases']):
   assert 2<=len(c['stages'])<=5 and any(o['correct'] for o in c['choices'])
   n=len(c['stages']);w=(900-(n-1)*25)/n;svg=SVG_HEAD+'aria-label="Schematic recovery stages for '+e(c['target'])+'. No heating apparatus is being operated.">'
   for j,label in enumerate(c['stages']):
    x=50+j*(w+25);svg+=f'<rect data-separation-node="{j}" x="{x}" y="145" width="{w}" height="165" rx="10" fill="#f1f5f9" stroke="#3f7d6e" stroke-width="3"/>'
    svg+=wrap_svg(label,x+w/2,185,w,23,max(12,int(w/13)),True)
    if j<n-1:svg+=f'<line x1="{x+w+3}" y1="230" x2="{x+w+20}" y2="230" stroke="#1f2937" stroke-width="4"/><path d="M{x+w+14} 220 L{x+w+24} 230 L{x+w+14} 240" fill="#1f2937"/>'
   svg+='<text x="50" y="395" font-size="24">Choose a method for the target you want to recover.</text><text x="50" y="436" font-size="22">The diagram is a sequence, not an apparatus or heating demonstration.</text></svg>'
   panels.append('<section data-separation-case="'+str(i)+'"'+(' hidden' if i else '')+'><p><b>Mixture:</b> '+e(c['mixture'])+'<br><b>Recover:</b> '+e(c['target'])+'</p><div class="lab-model-controls">'+''.join('<button type="button" data-separation-method="'+str(j)+'" data-correct="'+str(o['correct']).lower()+'" data-feedback="'+e(o['feedback'])+'" aria-pressed="false">'+e(o['method'])+'</button>' for j,o in enumerate(c['choices']))+'</div><button type="button" data-separation-run disabled>Test this method</button><p data-separation-feedback role="status" class="lab-feedback" hidden></p><div data-separation-process hidden>'+svg+'<button type="button" data-separation-next>Next process stage</button><p data-separation-stage class="lab-model-output" role="status" aria-live="polite"></p></div></section>')
  return '<div class="lab-model" data-model="separation" data-separation="'+e(json.dumps(sep))+'"><h4>Choose the recovery target</h4><div class="lab-model-controls">'+''.join('<button type="button" data-separation-select="'+str(i)+'" aria-pressed="'+str(i==0).lower()+'">'+e(c['name'])+'</button>' for i,c in enumerate(sep['cases']))+'</div>'+''.join(panels)+'<input type="hidden" data-note data-model-record aria-label="Separation chosen method"><p class="lab-animation-note">A filter can retain an insoluble solid. Dissolved salt passes through with the water. Evaporation leaves salt; recovering water also needs vapour to be condensed and collected.</p></div>'
 if mode=='glucose':
  g=spec['glucose'];assert len(g['coreStages'])>=4
  svg=SVG_HEAD+'aria-label="Qualitative blood-glucose control model. The indicator has no clinical scale, values or treatment instructions."><defs><marker id="'+uid+'-glucose-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7 Z" fill="#475569"/></marker></defs><text x="35" y="35" font-size="25">Qualitative blood glucose</text><rect x="245" y="75" width="85" height="360" rx="16" fill="#f8fafc" stroke="#64748b" stroke-width="3"/><rect x="245" y="213" width="85" height="75" fill="#dcecdf"/><text x="70" y="125" font-size="24">Raised</text><text x="35" y="257" font-size="24">Usual range</text><text x="85" y="401" font-size="24">Lower</text><circle class="glucose-marker" data-glucose-marker cx="287" cy="250" r="17" fill="#7a5c9e" stroke="#1f2937" stroke-width="3"/><rect x="515" y="63" width="390" height="88" rx="10" fill="#f0ebf5" stroke="#7a5c9e" stroke-width="3"/><text x="710" y="115" font-size="26" text-anchor="middle">Pancreas</text><line x1="710" y1="154" x2="710" y2="196" stroke="#475569" stroke-width="4" marker-end="url(#'+uid+'-glucose-arrow)"/><rect x="515" y="204" width="390" height="85" rx="10" fill="#f0ebf5" stroke="#7a5c9e" stroke-width="3"/><text data-glucose-hormone x="710" y="255" font-size="26" text-anchor="middle">Insulin signal</text><line x1="710" y1="292" x2="710" y2="334" stroke="#475569" stroke-width="4" marker-end="url(#'+uid+'-glucose-arrow)"/><rect x="515" y="342" width="390" height="94" rx="10" fill="#f0ebf5" stroke="#7a5c9e" stroke-width="3"/><text data-glucose-target x="710" y="395" font-size="25" text-anchor="middle">Body cells and liver</text><text x="50" y="478" font-size="23">Suitable limits, not one unchanging value. Positions are schematic.</text></svg>'
  buttons='<button type="button" data-glucose-route="core" aria-pressed="true">Core: raised glucose and insulin</button>'
  if g.get('higherStages'):buttons+='<button type="button" data-glucose-route="higher" aria-pressed="false">Optional Higher: lower glucose and glucagon</button>'
  return '<div class="lab-model" data-model="glucose" data-glucose="'+e(json.dumps(g))+'"><h4>Blood-glucose feedback explorer</h4><p>This is a qualitative teaching model. It has no clinical glucose readings, diagnosis, medication or dose controls.</p><div class="lab-model-controls">'+buttons+'</div><p data-glucose-tier class="lab-status">Core route: insulin response to raised blood glucose</p>'+svg+'<div class="lab-model-controls"><button type="button" data-glucose-next>Start the case</button><button type="button" data-glucose-reset>Reset this route</button></div><p data-glucose-stage class="lab-model-output" role="status" aria-live="polite"></p><input type="hidden" data-note data-model-record aria-label="Blood-glucose conceptual route"><p class="lab-animation-note">Move one explanatory stage at a time. Hormones act as signals; they do not turn into glucose or destroy it. The optional glucagon route is Higher stretch and is not needed for the core task.</p></div>'
 return ''

CSS=r'''
.lab-model svg [hidden]{display:none}.friction-runner [data-friction-force]{opacity:0}.friction-runner.replaying [data-friction-force]{opacity:1}.friction-runner{--friction-travel:0px;transform:translateX(0)}.friction-runner.replaying{animation:friction-record 2.6s ease-out forwards}.friction-runner.at-end{transform:translateX(var(--friction-travel))}.science-lab.is-paused .friction-runner.replaying{animation-play-state:paused}.glucose-marker{transition:cy .7s ease}.science-lab.is-paused .glucose-marker{transition:none}.lab-model [data-separation-node].current-node{fill:#dcecdf;stroke:#c9803b;stroke-width:5}.lab-model [data-separation-method][aria-pressed=true]{background:var(--ido-bg);color:#1f2937}@keyframes friction-record{from{transform:translateX(0)}to{transform:translateX(var(--friction-travel))}}@media(prefers-reduced-motion:reduce){.friction-runner.replaying [data-friction-force]{opacity:0}.friction-runner.replaying{animation:none;transform:translateX(var(--friction-travel))}.glucose-marker{transition:none}}
'''

JS=r'''
(function(){
'use strict';
document.querySelectorAll('[data-science-lab]').forEach(lab=>lab.querySelectorAll('[data-model]').forEach(model=>{
 const mode=model.dataset.model,record=model.querySelector('[data-model-record]');if(!['growth','friction','separation','glucose'].includes(mode))return;
 function keep(text){if(record)record.value=text;}
 if(mode==='growth'){
  const g=JSON.parse(model.dataset.growth);let index=0,clock=null,resumeWanted=false;
  const play=model.querySelector('[data-growth-play]');
  function stop(remember=false){resumeWanted=remember&&Boolean(clock);if(clock)clearInterval(clock);clock=null;play.textContent='Play records';}
  function show(){model.querySelectorAll('[data-growth-day]').forEach(el=>{if(Number(el.dataset.growthDay)>index)el.setAttribute('hidden','');else el.removeAttribute('hidden');});const text=g.dates[index]+' · Day '+g.days[index]+' · '+g.series.map(s=>s.name+': '+s.values[index]+' '+(g.unit||'cm')).join(' · ');model.querySelector('[data-growth-output]').textContent=text;keep(text+'\n'+g.note);model.querySelector('[data-growth-previous]').disabled=index===0;model.querySelector('[data-growth-next]').disabled=index===g.dates.length-1;}
  function start(){if(clock||lab.classList.contains('is-paused'))return;if(index===g.dates.length-1)index=0;show();play.textContent='Stop playback';resumeWanted=false;clock=setInterval(()=>{index=Math.min(index+1,g.dates.length-1);show();if(index===g.dates.length-1)stop(false);},1000);}
  play.addEventListener('click',()=>clock?stop(false):start());model.querySelector('[data-growth-previous]').addEventListener('click',()=>{stop(false);index=Math.max(0,index-1);show();});model.querySelector('[data-growth-next]').addEventListener('click',()=>{stop(false);index=Math.min(g.dates.length-1,index+1);show();});
  function reset(){stop(false);index=0;show();}model.querySelector('[data-growth-reset]').addEventListener('click',reset);lab.querySelector('[data-lab-reset]').addEventListener('click',reset);
  lab.querySelector('[data-lab-pause]').addEventListener('click',()=>{if(lab.classList.contains('is-paused'))stop(true);else{show();if(resumeWanted)start();}});document.querySelectorAll('[data-action="pause"]').forEach(b=>b.addEventListener('click',()=>stop(true)));document.addEventListener('visibilitychange',()=>{if(document.hidden)stop(true);});document.addEventListener('classic-slide-change',()=>{if(!lab.closest('.slide').classList.contains('active'))stop(false);});show();
 }
 if(mode==='friction'){
  const f=JSON.parse(model.dataset.friction);let surface=0;const runner=model.querySelector('[data-friction-runner]'),maximum=Math.max(...f.surfaces.map(s=>s.distanceCm));
  function show(){runner.classList.remove('replaying','at-end');const s=f.surfaces[surface],travel=s.distanceCm/maximum*620;runner.style.setProperty('--friction-travel',travel+'px');model.querySelector('[data-friction-end]').setAttribute('x1',130+travel);model.querySelector('[data-friction-end]').setAttribute('x2',130+travel);model.querySelector('[data-friction-end-label]').setAttribute('x',Math.max(250,100+travel));model.querySelector('[data-friction-end-label]').textContent=s.distanceCm+' cm';const text=s.name+': '+s.distanceCm+' cm supplied mean stopping distance'+(s.trials?' (trials: '+s.trials.join(', ')+' cm)':'')+'.';model.querySelector('[data-friction-output]').textContent=text;model.querySelectorAll('[data-friction-surface]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.frictionSurface)===surface)));keep(text+'\n'+f.note);}
  model.querySelectorAll('[data-friction-surface]').forEach(b=>b.addEventListener('click',()=>{surface=Number(b.dataset.frictionSurface);show();}));model.querySelector('[data-friction-play]').addEventListener('click',()=>{runner.classList.remove('replaying','at-end');if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){runner.classList.add('at-end');return;}runner.getBoundingClientRect();runner.classList.add('replaying');});runner.addEventListener('animationend',()=>{runner.classList.remove('replaying');runner.classList.add('at-end');});model.querySelector('[data-friction-endpoint]').addEventListener('click',()=>{runner.classList.remove('replaying');runner.classList.add('at-end');});model.querySelector('[data-friction-reset]').addEventListener('click',show);lab.querySelector('[data-lab-reset]').addEventListener('click',()=>{surface=0;show();});show();
 }
 if(mode==='separation'){
  const sep=JSON.parse(model.dataset.separation);let current=0;const panels=Array.from(model.querySelectorAll('[data-separation-case]'));
  function select(i){current=i;panels.forEach((p,k)=>p.hidden=k!==i);model.querySelectorAll('[data-separation-select]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.separationSelect)===i)));keep(sep.cases[i].name+': no method tested yet.');}
  panels.forEach((p,i)=>{let stage=0;const c=sep.cases[i];function show(){p.querySelectorAll('[data-separation-node]').forEach(n=>n.classList.toggle('current-node',Number(n.dataset.separationNode)===stage));p.querySelector('[data-separation-stage]').textContent=(stage+1)+'/'+c.stages.length+' · '+c.stages[stage];p.querySelector('[data-separation-next]').disabled=stage===c.stages.length-1;keep(c.name+' — Recover '+c.target+'\n'+c.stages.slice(0,stage+1).join(' → '));}
   p.querySelectorAll('[data-separation-method]').forEach(b=>b.addEventListener('click',()=>{p.querySelectorAll('[data-separation-method]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));p.querySelector('[data-separation-run]').disabled=false;p.querySelector('[data-separation-feedback]').hidden=true;p.querySelector('[data-separation-process]').hidden=true;}));
   p.querySelector('[data-separation-run]').addEventListener('click',()=>{const b=p.querySelector('[data-separation-method][aria-pressed=true]');if(!b)return;const feedback=p.querySelector('[data-separation-feedback]');feedback.textContent=b.dataset.feedback;feedback.hidden=false;feedback.dataset.result=b.dataset.correct==='true'?'correct':'incorrect';p.querySelector('[data-separation-process]').hidden=b.dataset.correct!=='true';keep(c.name+' — '+b.textContent+'\n'+b.dataset.feedback);if(b.dataset.correct==='true'){stage=0;show();}});
   p.querySelector('[data-separation-next]').addEventListener('click',()=>{stage=Math.min(stage+1,c.stages.length-1);show();});lab.querySelector('[data-lab-reset]').addEventListener('click',()=>{stage=0;p.querySelectorAll('[data-separation-method]').forEach(b=>b.setAttribute('aria-pressed','false'));p.querySelector('[data-separation-run]').disabled=true;p.querySelector('[data-separation-feedback]').hidden=true;p.querySelector('[data-separation-process]').hidden=true;});
  });model.querySelectorAll('[data-separation-select]').forEach(b=>b.addEventListener('click',()=>select(Number(b.dataset.separationSelect))));lab.querySelector('[data-lab-reset]').addEventListener('click',()=>select(0));select(0);
 }
 if(mode==='glucose'){
  const g=JSON.parse(model.dataset.glucose);let route='core',stage=0;const next=model.querySelector('[data-glucose-next]');
  function list(){return route==='higher'?g.higherStages:g.coreStages;}
  function show(){const s=list()[stage],positions={usual:250,raised:115,lower:391,towards:route==='higher'?307:192};model.querySelector('[data-glucose-marker]').setAttribute('cy',positions[s.level]);model.querySelector('[data-glucose-hormone]').textContent=route==='higher'?'Glucagon signal':'Insulin signal';model.querySelector('[data-glucose-target]').textContent=route==='higher'?'Liver: glucose released':'Body cells and liver';model.querySelector('[data-glucose-tier]').textContent=route==='higher'?'Optional Higher stretch: glucagon response to lower glucose':'Core route: insulin response to raised blood glucose';model.querySelectorAll('[data-glucose-route]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.glucoseRoute===route)));const text=(stage+1)+'/'+list().length+' · '+s.label+' — '+s.explanation;model.querySelector('[data-glucose-stage]').textContent=text;keep((route==='higher'?'Optional Higher':'Core')+'\n'+text);next.disabled=stage===list().length-1;next.textContent=stage===0?'Start the case':stage===list().length-1?'Case explained':'Next response stage';}
  model.querySelectorAll('[data-glucose-route]').forEach(b=>b.addEventListener('click',()=>{route=b.dataset.glucoseRoute;stage=0;show();}));next.addEventListener('click',()=>{stage=Math.min(stage+1,list().length-1);show();});model.querySelector('[data-glucose-reset]').addEventListener('click',()=>{stage=0;show();});lab.querySelector('[data-lab-reset]').addEventListener('click',()=>{route='core';stage=0;show();});show();
 }
}));
}());
'''
